<?php
require $argv[1];
function check($ok,$message){if(!$ok){throw new RuntimeException($message);}}
$id='UCBrib_Esy01Ma_97Ae_BCRA';$video='M5hZAL_hW7c';
foreach(['https://www.youtube.com/@divinemediaUS','https://youtube.com/channel/'.$id.'/videos','https://youtu.be/'.$video.'?si=share','https://youtube.com/shorts/'.$video]as $url){check(DivineYouTube::source($url)!==null,'Supported URL rejected');}
foreach(['https://youtube.com.evil.test/@channel','https://youtube.com@evil.test/watch?v='.$video,'https://youtube.com:443/@channel','file:///secret','https://youtube.com/watch?v[]=bad','https://youtube.com/playlist?list=bad']as $url){check(DivineYouTube::source($url)===null,'Untrusted URL accepted');}
check(DivineYouTube::channelIdFromHtml('<link rel="canonical" href="https://www.youtube.com/channel/'.$id.'">')===$id,'Canonical identity failed');
check(DivineYouTube::channelIdFromHtml('<link rel="canonical" href="https://www.youtube.com.evil.test/channel/'.$id.'">')===null,'Spoofed identity accepted');
$xml='<feed xmlns="http://www.w3.org/2005/Atom" xmlns:yt="http://www.youtube.com/xml/schemas/2015" xmlns:media="http://search.yahoo.com/mrss/"><yt:channelId>'.$id.'</yt:channelId><title>Divine Media</title><entry><yt:videoId>'.$video.'</yt:videoId><title>Channel video</title><published>2026-11-01T00:00:00Z</published><media:group><media:description>Public description</media:description></media:group></entry></feed>';
$shortFeed=DivineYouTube::feed(str_replace('<yt:channelId>'.$id,'<yt:channelId>'.substr($id,2),$xml),$id);check(count($shortFeed['items'])===1,'Unprefixed official channel ID rejected');
$preview=(new DivineYouTube(function($url)use($id,$xml){$p=parse_url($url);check(in_array($p['host'],['www.googleapis.com','www.youtube.com'],true),'Unexpected provider host');if($p['host']==='www.googleapis.com'){return ['status'=>403,'body'=>json_encode(['error'=>['errors'=>[['reason'=>'quotaExceeded']]]])];}if(str_contains($url,'feeds/videos.xml')){return ['status'=>200,'body'=>$xml];}return ['status'=>200,'body'=>'<link rel="canonical" href="https://www.youtube.com/channel/'.$id.'">'];}))->preview(DivineYouTube::source('https://www.youtube.com/@divinemediaUS'),'synthetic-key');
check($preview['mode']==='feed'&&count($preview['items'])===1&&$preview['next']===null,'Quota fallback incomplete');check($preview['items'][0]['thumbs']==='https://i.ytimg.com/vi/'.$video.'/hqdefault.jpg','Fixed thumbnail host missing');
try{DivineYouTube::feed(str_replace($id,'UC0000000000000000000000',$xml),$id);throw new LogicException('Wrong channel accepted');}catch(RuntimeException $e){}
try{DivineYouTube::feed('<!DOCTYPE feed [<!ENTITY a SYSTEM "file:///secret">]>'.$xml,$id);throw new LogicException('DTD accepted');}catch(RuntimeException $e){}
$client=new DivineYouTube(function($url)use($id,$video){$path=parse_url($url,PHP_URL_PATH);if(str_ends_with($path,'channels')){$data=['items'=>[['id'=>$id,'snippet'=>['title'=>'Divine Media'],'contentDetails'=>['relatedPlaylists'=>['uploads'=>'UUtest']]]]];}elseif(str_ends_with($path,'playlistItems')){$data=['items'=>[['contentDetails'=>['videoId'=>$video]]],'nextPageToken'=>'page-two'];}else{$data=['items'=>[['id'=>$video,'snippet'=>['title'=>'Public video'],'contentDetails'=>['duration'=>'PT5M'],'status'=>['privacyStatus'=>'public','embeddable'=>true]],['id'=>'00000000000','snippet'=>['title'=>'Private video'],'status'=>['privacyStatus'=>'private','embeddable'=>true]],['id'=>'11111111111','snippet'=>['title'=>'Blocked video'],'status'=>['privacyStatus'=>'public','embeddable'=>false]]]];}return ['status'=>200,'body'=>json_encode($data)];});
$preview=$client->preview(DivineYouTube::source('https://www.youtube.com/channel/'.$id),'synthetic-key');check(count($preview['items'])===1&&$preview['next']==='page-two','Privacy, embeddability or pagination failed');
$single=(new DivineYouTube(fn($url)=>['status'=>200,'body'=>json_encode(['title'=>'Single video','author_name'=>'Creator'])]))->preview(DivineYouTube::source('https://youtu.be/'.$video),'');check($single['mode']==='single'&&count($single['items'])===1,'Single preview requires API key');
echo json_encode(['result'=>'pass','strict_sources'=>true,'quota_feed_fallback'=>true,'feed_identity_and_xml_safety'=>true,'private_and_embedding_disabled_filtered'=>true,'pagination'=>true,'single_without_api_key'=>true]);

$meta=(new DivineYouTube(function($url)use($video){parse_str(parse_url($url,PHP_URL_QUERY),$q);check(str_contains($q['part'],'statistics'),'Statistics not requested');return ['status'=>200,'body'=>json_encode(['items'=>[['id'=>$video,'snippet'=>['title'=>'Test','tags'=>['music']],'contentDetails'=>['duration'=>'PT1M'],'status'=>['privacyStatus'=>'public','embeddable'=>true],'statistics'=>['viewCount'=>'120','likeCount'=>'0','commentCount'=>'9','dislikeCount'=>'44','shares'=>'99']]]])];}))->metadata($video,'synthetic-key');
check($meta['providerMetadata']['statistics']===['viewCount'=>'120','likeCount'=>'0','commentCount'=>'9'],'Public statistics allowlist failed');
check($meta['providerMetadata']['tags']===['music'],'Source tags missing');
try{(new DivineYouTube(fn($url)=>['status'=>200,'body'=>json_encode(['items'=>[['status'=>['privacyStatus'=>'private','embeddable'=>true]]]])]))->metadata($video,'synthetic-key');throw new LogicException('Private metadata exposed');}catch(RuntimeException $e){}
echo "\nYouTube metadata allowlist and privacy: pass\n";
